<script setup>
import {computed, onMounted, ref} from 'vue';
import {supabase} from '../../lib/supabase';
import {comboCode, comboRecipeRequirement} from '../../lib/battle/comboRules.js';
import {normalizeTcgType} from '../../utils/tcgTypes.js';
const props = defineProps({cards:{type:Array, default:()=>[]}});
const types=['knight','fire','water','forest','thunder','light','dark'];
const rows=ref([]), draft=ref(null), loading=ref(false), saving=ref(false), error=ref(''), notice=ref(''), search=ref('');
const copy=value=>JSON.parse(JSON.stringify(value));
const visible=computed(()=>rows.value.filter(row=>`${row.combo_name} ${row.rule_kind} ${comboRecipeRequirement(row)}`.toLowerCase().includes(search.value.toLowerCase())));
const baseCards=computed(()=>props.cards.filter(card=>!card.fusion_only&&!card.archived_at));
const tags=computed(()=>[...new Set(baseCards.value.flatMap(card=>card.tags||[]))].filter(tag=>!tag.toLowerCase().startsWith('fusion:')).sort());
const count=computed(()=>draft.value?.members.length||2);
const kindLabel=n=>n===4?'Formation':n===3?'Triple Combo':'Combo pasangan';
function edit(row){draft.value={...copy(row),members:row.members?.length?copy(row.members):row.type_keys.map(type=>({type,card_code:'',tag:''})),shared_tag:row.shared_tag||false,priority:row.priority||0};notice.value='';error.value='';}
function create(){edit({combo_name:'',enabled:true,type_keys:['fire','thunder'],primary_multiplier:1,assist_multipliers:[.5],damage_multiplier:1,bonus_damage:0,defense_ignore_pct:0,heal_after:0,shield_after:0,status_key:null,status_target:'enemy',effect_json:{summary:'',cleanse_negative_status:false}});}
function changeCount(event){const size=Number(event.target.value);while(draft.value.members.length<size)draft.value.members.push({type:'forest',card_code:'',tag:''});draft.value.members=draft.value.members.slice(0,size);draft.value.assist_multipliers=Array.from({length:size-1},(_,i)=>draft.value.assist_multipliers[i]??.5);}
function pickCode(member){const card=baseCards.value.find(card=>comboCode(card.card_code)===comboCode(member.card_code));if(card&&normalizeTcgType(card.element))member.type=normalizeTcgType(card.element);}
const preview=computed(()=>draft.value?{...draft.value,type_keys:draft.value.members.map(member=>member.type)}:null);
async function load(){if(loading.value||saving.value)return;loading.value=true;error.value='';try{const result=await supabase.from('tcg_combo_rule_catalog').select('*').order('id');if(result.error)throw result.error;rows.value=result.data||[];const selected=rows.value.find(row=>row.id===draft.value?.id)||rows.value[0];selected?edit(selected):create();}catch(err){error.value='Resep belum dapat dimuat. '+err.message;}finally{loading.value=false;}}
async function save(){if(saving.value)return;saving.value=true;error.value='';notice.value='';try{
 const row=copy(draft.value);row.type_keys=row.members.map(member=>member.type).sort();row.rule_kind=count.value===4?'formation':count.value===3?'triple':row.type_keys[0]===row.type_keys[1]?'same':'pair';
 row.members=row.members.map(member=>({...member,card_code:member.card_code?.trim()||'',tag:member.tag?.trim()||''}));
 const result=await supabase.rpc('save_combo_recipe',{p_rule:row});if(result.error)throw result.error;
 rows.value=[...rows.value.filter(item=>item.id!==result.data.id),result.data].sort((a,b)=>a.id-b.id);edit(result.data);notice.value='Resep disimpan untuk battle baru. Pertandingan yang sudah dibuat tetap memakai resep awal.';
 }catch(err){error.value=err.code==='23505'?'Nama resep sudah digunakan. Gunakan nama lain.':err.message||'Gagal menyimpan resep.';}finally{saving.value=false;}}
onMounted(load);
</script>
<template>
 <section class="combo-catalog" aria-label="Pengaturan resep Combo">
  <header class="combo-catalog-heading"><div><span class="combo-kicker">STRATEGI TIM</span><h2>Resep Combo</h2><p>Tentukan siapa yang bisa bekerja sama dan bonus yang dihasilkan.</p></div><button type="button" @click="load" :disabled="loading||saving">Muat ulang</button></header>
  <div class="combo-catalog-guide"><b>Satu tim, satu cooldown</b><p>Battle baru: kartu Base saja, maksimal satu Combo per giliran. Setelah berhasil, lewati satu giliranmu tanpa Combo. Generic, pasangan, Triple, dan Formation berbagi jatah ini.</p><p>Generic: 2 kartu tanpa resep yang cocok → 100% ATK utama + 50% ATK pendamping, tanpa bonus. Triple dan Formation wajib cocok dengan resep. Semua peserta memakai jatah serang dan tidak boleh mundur sampai giliran pemilik berikutnya.</p><small>Biaya default: 2 AP untuk pasangan / Generic, 3 AP untuk Triple / Formation. Biaya sebenarnya mengikuti Game Setup. Perubahan resep hanya untuk battle baru.</small></div>
  <p v-if="error" class="combo-feedback error" role="alert">{{error}}</p><p v-if="notice" class="combo-feedback" role="status">{{notice}}</p>
  <p v-if="loading" role="status">Memuat resep…</p>
  <div v-else class="combo-catalog-workspace">
   <aside><button type="button" class="combo-add" @click="create" :disabled="saving">+ Buat resep</button><input v-model="search" aria-label="Cari resep Combo" placeholder="Cari nama, tipe, atau tag…"><div class="combo-catalog-list"><button v-for="row in visible" :key="row.id" type="button" :class="{selected:row.id===draft?.id}" @click="edit(row)" :disabled="saving"><b>{{row.combo_name}}</b><small>{{kindLabel(row.type_keys.length)}} · {{row.enabled?'Aktif':'Nonaktif'}}</small></button><p v-if="!visible.length">Belum ada resep yang cocok.</p></div></aside>
   <form v-if="draft" @submit.prevent="save">
    <header><h3>{{draft.id?'Edit resep':'Resep baru'}}</h3><label class="combo-check"><input v-model="draft.enabled" type="checkbox">Aktif</label></header>
    <fieldset :disabled="saving"><legend>1. Nama dan peserta</legend>
     <div class="combo-form-grid"><label>Nama resep<input v-model="draft.combo_name" required maxlength="100" placeholder="Contoh: Thunder Patrol"></label><label>Jenis Combo<select :value="count" @change="changeCount"><option :value="2">Pasangan · 2 kartu</option><option :value="3">Triple Combo · 3 kartu</option><option :value="4">Formation · 4 kartu</option></select></label></div>
     <p class="combo-help">Satu baris = satu kartu berbeda. Urutan peserta bebas. Kode kartu dan tag boleh kosong; jika diisi, semua syarat pada baris tersebut harus dipenuhi.</p>
     <div v-for="(member,index) in draft.members" :key="index" class="combo-member"><b>Peserta {{index+1}}</b><label>Tipe<select v-model="member.type"><option v-for="type in types" :key="type" :value="type">{{type}}</option></select></label><label>Kartu tertentu · opsional<input v-model="member.card_code" list="combo-card-codes" placeholder="Contoh: COB-008" maxlength="100" @change="pickCode(member)"></label><label>Tag wajib · opsional<input v-model="member.tag" list="combo-card-tags" placeholder="Contoh: THUNDER TEAM" maxlength="100"></label></div>
     <datalist id="combo-card-codes"><option v-for="card in baseCards" :key="card.id" :value="comboCode(card.card_code)">{{card.name}}</option></datalist><datalist id="combo-card-tags"><option v-for="tag in tags" :key="tag" :value="tag"/></datalist>
     <label class="combo-check"><input v-model="draft.shared_tag" type="checkbox">Semua peserta juga harus memiliki satu tag yang sama</label><small class="combo-help">Tag fusion: tidak dihitung. Gunakan tag kartu yang sudah ada atau tambahkan tag khusus melalui Card Studio.</small>
    </fieldset>
    <fieldset :disabled="saving"><legend>2. Kekuatan serangan</legend><p class="combo-help">Pemain memilih kartu utama. Pendamping dihitung sesuai urutan pilihan. Angka 1 = 100%, 0.5 = 50%.</p>
     <div class="combo-form-grid"><label>Pengali ATK utama<input v-model.number="draft.primary_multiplier" type="number" min="0" max="2" step="0.05" required></label><label v-for="(_,index) in draft.assist_multipliers" :key="index">Pengali pendamping {{index+1}}<input v-model.number="draft.assist_multipliers[index]" type="number" min="0" max="1" step="0.05" required></label><label>Bonus damage<input v-model.number="draft.bonus_damage" type="number" min="0" max="50" required></label><label>Pengali hasil total<input v-model.number="draft.damage_multiplier" type="number" min="0" max="1.5" step="0.05" required></label><label>Bagian DEF diabaikan · 0–1<input v-model.number="draft.defense_ignore_pct" type="number" min="0" max="1" step="0.05" required></label></div>
    </fieldset>
    <fieldset :disabled="saving"><legend>3. Efek tambahan</legend><div class="combo-form-grid"><label>Pulihkan HP setiap peserta<input v-model.number="draft.heal_after" type="number" min="0" max="50" required></label><label>Shield untuk kartu utama<input v-model.number="draft.shield_after" type="number" min="0" max="50" required></label><label>Status tambahan<select v-model="draft.status_key"><option :value="null">Tidak ada</option><option v-for="status in ['burn','poison','freeze','stun','root','curse','shield']" :key="status" :value="status">{{status}}</option></select></label><label>Penerima status<select v-model="draft.status_target"><option value="enemy">Target lawan yang bertahan</option><option value="primary">Kartu utama</option><option value="participants">Semua peserta</option></select></label><label>Prioritas resep · 0–100<input v-model.number="draft.priority" type="number" min="0" max="100" required><small>Angka terbesar dipilih. Jika sama, resep kartu/tag yang lebih spesifik diutamakan, lalu resep yang dibuat lebih dulu.</small></label></div><label class="combo-check"><input v-model="draft.effect_json.cleanse_negative_status" type="checkbox">Bersihkan status negatif seluruh peserta</label><label>Penjelasan singkat<textarea v-model="draft.effect_json.summary" rows="2" maxlength="1000" placeholder="Jelaskan efek resep untuk pemain."/></label></fieldset>
    <div class="combo-catalog-preview" aria-label="Pratinjau resep"><b>{{draft.combo_name||'Nama resep'}} · {{kindLabel(count)}}</b><p>{{comboRecipeRequirement(preview)}}</p><p>ATK utama × {{draft.primary_multiplier}} + ATK pendamping × {{draft.assist_multipliers.join(' / ')}} + {{draft.bonus_damage}} bonus; hasil × {{draft.damage_multiplier}}, lalu kurangi DEF efektif target.</p><small>Damage akhir juga mengikuti efek battle. Shield, status, dan cleanse memerlukan Status Effects aktif. Pemulihan mengenai HP kartu peserta, bukan HP pemain.</small></div>
    <button class="combo-save" type="submit" :disabled="saving">{{saving?'Menyimpan…':'Simpan resep Combo'}}</button>
   </form>
  </div>
 </section>
</template>
<style scoped>
.combo-catalog{color:#244333}.combo-catalog-heading,.combo-catalog form>header{display:flex;justify-content:space-between;align-items:start;gap:16px}.combo-catalog h2{margin:5px 0 10px;font-size:28px;letter-spacing:-.6px}.combo-kicker{font-size:10px;letter-spacing:1.8px;font-weight:800;color:#7562a4}.combo-catalog p{font-size:13px;line-height:1.7}.combo-catalog button{padding:11px 14px;border:1px solid #cedbd3;border-radius:9px;background:#fff;color:#315443;cursor:pointer;font-weight:700}.combo-catalog button:disabled{opacity:.55;cursor:not-allowed}.combo-catalog-guide{margin:22px 0;padding:20px 24px;border:1px solid #d9cee9;border-left:4px solid #78569e;border-radius:12px;background:#f7f3fc}.combo-catalog-guide p{margin:8px 0}.combo-catalog small{font-size:11px;line-height:1.7;color:#5f7268}.combo-catalog-workspace{display:grid;grid-template-columns:240px minmax(0,1fr);gap:20px}.combo-catalog-workspace>aside{align-self:start;display:grid;gap:10px}.combo-catalog-list{max-height:700px;overflow:auto;display:grid;gap:8px}.combo-catalog-list button{display:grid;gap:6px;text-align:left}.combo-catalog-list button.selected{background:#f1ecf8;border-color:#957bb4;color:#593980}.combo-catalog form{padding:24px;border:1px solid #d8e3dc;border-radius:14px;background:#fff;min-width:0}.combo-catalog h3{margin:0 0 18px}.combo-catalog fieldset{margin:20px 0;padding:18px;border:1px solid #dce5df;border-radius:10px;min-width:0}.combo-catalog legend{padding:0 8px;font-size:13px;font-weight:800}.combo-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.combo-catalog label{display:grid;gap:7px;font-size:12px;font-weight:650;min-width:0}.combo-catalog :is(input,select,textarea){box-sizing:border-box;width:100%;padding:10px 12px;border:1px solid #cfded4;border-radius:8px;background:#fff;color:#234734;min-width:0;font:inherit;font-size:13px}.combo-catalog .combo-check{display:flex;align-items:center;gap:9px;margin:14px 0}.combo-check input{width:17px;height:17px;flex:none}.combo-help{display:block;color:#5f7268;font-size:12px}.combo-member{display:grid;grid-template-columns:65px .7fr 1fr 1fr;gap:10px;align-items:center;margin:12px 0;padding:12px;background:#f6f8f5;border-radius:9px}.combo-member>b{font-size:11px}.combo-catalog-preview{padding:18px;border:1px solid #d8c6ed;background:#faf6ff;border-radius:12px;margin:20px 0}.combo-catalog .combo-save{background:#68468c;border-color:#68468c;color:#fff}.combo-feedback{padding:14px;background:#eef8ec;border:1px solid #bbd8b6;border-radius:9px}.combo-feedback.error{background:#fff4ed;border-color:#efc7ae;color:#923d26}.combo-catalog :is(input,select,textarea,button):focus-visible{outline:3px solid #3595a6;outline-offset:3px}@media(max-width:1100px){.combo-catalog-workspace{grid-template-columns:1fr}.combo-catalog-list{max-height:230px;grid-template-columns:repeat(2,minmax(0,1fr))}.combo-member{grid-template-columns:1fr 1fr}.combo-member>b{grid-column:1/-1}}@media(max-width:600px){.combo-catalog-heading{flex-wrap:wrap}.combo-form-grid,.combo-member,.combo-catalog-list{grid-template-columns:1fr}.combo-catalog form{padding:15px}.combo-catalog fieldset{padding:12px}}
</style>
